using System.Text.Json;
using AcroFunJam.Domain.Catalog;
using AcroFunJam.Domain.SharedKernel;
using AcroFunJam.Infrastructure.Videos;

namespace AcroFunJam.Infrastructure.Tests.Videos;

/// <summary>
/// ffprobe and ffmpeg run for real (story 12, V4 to V10, ADR 0041), on files generated by ffmpeg during the test: the format is
/// recognised from the content, the duration found at the demultiplexing, never in the header; the prepared video has no sound and
/// no metadata, is turned upright, resized to 720 px at most on its shorter side, with its first image as poster.
/// </summary>
[Trait("Category", "Integration")]
public sealed class FfmpegVideoProcessorTests : IDisposable
{
    private static CancellationToken Ct => TestContext.Current.CancellationToken;

    private readonly VideoProcessingOptions _options = new() { WorkDirectory = Path.Combine(Path.GetTempPath(), "acrofunjam-tests-" + Guid.NewGuid()) };
    private readonly FfmpegVideoProcessor _processor;

    public FfmpegVideoProcessorTests()
    {
        TestVideoFixtures.SkipWithoutFfmpeg();
        var probe = new FfprobeVideoProbe(_options);
        _processor = new FfmpegVideoProcessor(probe, new FfmpegVideoPreparer(_options, probe));
    }

    public void Dispose()
    {
        if (Directory.Exists(_options.WorkDirectory)) Directory.Delete(_options.WorkDirectory, recursive: true);
    }

    // --- Probing (V4 to V7) ---------------------------------------------------------------------

    [Theory]
    [InlineData(2, 2000)]
    [InlineData(30, 30_000)]
    [InlineData(30.9, 30_933)]
    [InlineData(31, 31_000)]
    [InlineData(1, 1000)]
    public async Task Probe_Should_FindTheDurationOfThePackets_When_TheVideoIsAnMp4(double seconds, long milliseconds)
    {
        var probe = await _processor.Probe(await TestVideoFixtures.Mp4(seconds), Ct);

        probe.Format.ShouldBe(VideoFormat.Mp4);
        probe.Dimensions.ShouldBe(new VideoDimensions(854, 480));
        probe.Duration!.Milliseconds.ShouldBeInRange(milliseconds - 70, milliseconds);
    }

    [Fact]
    public async Task Probe_Should_FindTheUprightDimensions_When_AnIPhoneFilmedInPortrait()
    {
        var probe = await _processor.Probe(await TestVideoFixtures.IPhoneMov(), Ct);

        probe.Format.ShouldBe(VideoFormat.QuickTime);
        probe.Dimensions.ShouldBe(new VideoDimensions(480, 854));
        probe.Duration!.Milliseconds.ShouldBeInRange(11_900, 12_000);
    }

    [Fact]
    public async Task Probe_Should_RecogniseAWebM_When_ItIsAVp9Video()
    {
        var probe = await _processor.Probe(await TestVideoFixtures.WebM(), Ct);

        probe.Format.ShouldBe(VideoFormat.WebM);
        probe.Dimensions.ShouldBe(new VideoDimensions(854, 480));
    }

    [Fact]
    public async Task Probe_Should_FindNoFormat_When_TheFileIsAGifOrAPhoto()
    {
        (await _processor.Probe(await TestVideoFixtures.Gif(), Ct)).Format.ShouldBeNull();
        (await _processor.Probe(await TestVideoFixtures.Jpeg(), Ct)).Format.ShouldBeNull();
    }

    [Fact]
    public async Task Probe_Should_FindTheRealDuration_When_TheHeaderLies()
    {
        var probe = await _processor.Probe(await TestVideoFixtures.LyingMp4(), Ct);

        probe.Duration!.Milliseconds.ShouldBeGreaterThan(39_000);
        VideoFile.Accept(probe.Format, VideoFileSize.Create(1).Value!, probe.Dimensions, probe.Duration).Error!.Code.ShouldBe("video.too-long");
    }

    [Fact]
    public async Task Probe_Should_FindItUnreadable_When_ItHasMorePacketsThanTheLongestVideoAtTheHighestRate()
    {
        var probe = await _processor.Probe(await TestVideoFixtures.ManyPackets(), Ct);

        probe.Format.ShouldBe(VideoFormat.Mp4);
        probe.Dimensions.ShouldBeNull();
        probe.Duration.ShouldBeNull();
    }

    [Fact]
    public async Task Probe_Should_FindItUnreadable_When_TheFileIsTruncated()
    {
        var probe = await _processor.Probe(await TestVideoFixtures.TruncatedMp4(), Ct);

        probe.Format.ShouldBe(VideoFormat.Mp4);
        probe.Dimensions.ShouldBeNull();
        probe.Duration.ShouldBeNull();
    }

    [Fact]
    public async Task Probe_Should_FindNoFormat_When_ATextFileIsNamedLikeAVideo()
    {
        var path = Path.Combine(Path.GetTempPath(), $"pop-to-bird-{Guid.NewGuid()}.mp4");
        await File.WriteAllTextAsync(path, "Pop to Bird, notes de jam", Ct);
        try
        {
            (await _processor.Probe(path, Ct)).ShouldBe(new AcroFunJam.Application.Catalog.VideoProbe(null, null, null));
        }
        finally
        {
            File.Delete(path);
        }
    }

    // --- Preparing (V8 to V10) ------------------------------------------------------------------

    [Fact]
    public async Task Prepare_Should_RemoveTheSoundAndEveryMetadataAndTurnTheVideoUpright_When_AnIPhoneFilmedIt()
    {
        var original = await TestVideoFixtures.IPhoneMov();
        var probe = await _processor.Probe(original, Ct);

        await using var prepared = (await _processor.Prepare(original, probe.Dimensions!.Presented(), Ct)).Value!;

        prepared.Outcome.Dimensions.ShouldBe(new VideoDimensions(480, 854));
        prepared.Outcome.Duration.Milliseconds.ShouldBeInRange(11_800, 12_100);
        var described = await TestVideoFixtures.Describe(prepared.VideoPath);
        var streams = described.GetProperty("streams").EnumerateArray().ToList();
        streams.Select(s => s.GetProperty("codec_type").GetString()).ShouldBe(["video"]);
        var video = streams.Single();
        video.GetProperty("codec_name").GetString().ShouldBe("h264");
        video.GetProperty("width").GetInt32().ShouldBe(480);
        video.GetProperty("height").GetInt32().ShouldBe(854);
        video.TryGetProperty("side_data_list", out var sideData).ShouldBeFalse(sideData.ToString());
        Tags(described.GetProperty("format")).ShouldNotContain(t => t.Contains("location") || t.Contains("model") || t.Contains("creation_time"));
        Tags(video).ShouldNotContain(t => t.Contains("creation_time") || t.Contains("rotate"));
        File.Exists(prepared.PosterPath).ShouldBeTrue();
    }

    [Theory]
    [InlineData(3840, 2160, 1280, 720)]
    [InlineData(854, 480, 854, 480)]
    public async Task Prepare_Should_PresentTheVideoIn720PixelsAtMost_When_NeverEnlargingIt(int width, int height, int presentedWidth, int presentedHeight)
    {
        var original = await TestVideoFixtures.Mp4(2, width, height);
        var probe = await _processor.Probe(original, Ct);

        await using var prepared = (await _processor.Prepare(original, probe.Dimensions!.Presented(), Ct)).Value!;

        prepared.Outcome.Dimensions.ShouldBe(new VideoDimensions(presentedWidth, presentedHeight));
    }

    [Fact]
    public async Task Prepare_Should_TakeTheFirstImageOfThePreparedVideoAsPoster_When_ItIsPrepared()
    {
        var original = await TestVideoFixtures.Mp4(2);

        await using var prepared = (await _processor.Prepare(original, new VideoDimensions(854, 480), Ct)).Value!;

        var poster = await TestVideoFixtures.Describe(prepared.PosterPath);
        var image = poster.GetProperty("streams").EnumerateArray().Single();
        image.GetProperty("codec_name").GetString().ShouldBe("webp");
        image.GetProperty("width").GetInt32().ShouldBe(854);
        image.GetProperty("height").GetInt32().ShouldBe(480);
    }

    [Fact]
    public async Task Prepare_Should_ConvertTheColoursToSdr_When_TheVideoWasFilmedInHdr()
    {
        await using var prepared = (await _processor.Prepare(await TestVideoFixtures.HlgMov(), new VideoDimensions(1280, 720), Ct)).Value!;

        var video = (await TestVideoFixtures.Describe(prepared.VideoPath)).GetProperty("streams").EnumerateArray().Single();
        video.GetProperty("pix_fmt").GetString().ShouldBe("yuv420p");
        video.GetProperty("color_transfer").GetString().ShouldBe("bt709");
    }

    [Fact]
    public async Task Prepare_Should_PrepareAWebM_When_ItIsAVp9Video()
    {
        await using var prepared = (await _processor.Prepare(await TestVideoFixtures.WebM(), new VideoDimensions(854, 480), Ct)).Value!;

        prepared.Outcome.Duration.Milliseconds.ShouldBeInRange(2_900, 3_100);
    }

    [Fact]
    public async Task Prepare_Should_BoundTheDecodingAndTellTheDecodedDuration_When_TheHeaderLied()
    {
        await using var prepared = (await _processor.Prepare(await TestVideoFixtures.LyingMp4(), new VideoDimensions(640, 480), Ct)).Value!;

        prepared.Outcome.Duration.ExceedsTheLimitByMoreThanTheTolerance.ShouldBeTrue();
        prepared.Outcome.Duration.Milliseconds.ShouldBeLessThanOrEqualTo(32_100);
    }

    [Fact]
    public async Task Prepare_Should_FailWithUnreadableAndLeaveNoFile_When_TheFileIsDamaged()
    {
        (await _processor.Prepare(await TestVideoFixtures.TruncatedMp4(), new VideoDimensions(854, 480), Ct)).Error.ShouldBe(VideoContentErrors.Unreadable);

        (Directory.Exists(_options.WorkDirectory) ? Directory.GetFiles(_options.WorkDirectory) : []).ShouldBeEmpty();
    }

    [Fact]
    public async Task Prepare_Should_DeleteItsFiles_When_TheyAreDisposed()
    {
        var prepared = (await _processor.Prepare(await TestVideoFixtures.Mp4(2), new VideoDimensions(854, 480), Ct)).Value!;

        await prepared.DisposeAsync();

        File.Exists(prepared.VideoPath).ShouldBeFalse();
        File.Exists(prepared.PosterPath).ShouldBeFalse();
    }

    private static IEnumerable<string> Tags(JsonElement element) =>
        element.TryGetProperty("tags", out var tags) ? tags.EnumerateObject().Select(t => $"{t.Name}={t.Value}") : [];

    [Fact]
    public void Recognise_Should_FindNoFormat_When_TheHeadIsTooShort() =>
        VideoContainerSniffer.Recognise([0, 0, 0, 0x18]).ShouldBeNull();

    [Fact]
    public void Recognise_Should_RefuseAHeifPhotoAndAMatroska_When_TheirHeadIsRead()
    {
        VideoContainerSniffer.Recognise("\0\0\0\u0018ftypheic\0\0\0\0"u8.ToArray().AsSpan()).ShouldBeNull();
        byte[] matroska = [0x1A, 0x45, 0xDF, 0xA3, 0x9F, 0x42, 0x86, 0x81, 0x01, 0x42, 0x82, 0x88, .. "matroska"u8.ToArray()];
        VideoContainerSniffer.Recognise(matroska).ShouldBeNull();
        byte[] webm = [0x1A, 0x45, 0xDF, 0xA3, 0x9F, 0x42, 0x86, 0x81, 0x01, 0x42, 0x82, 0x84, .. "webm"u8.ToArray()];
        VideoContainerSniffer.Recognise(webm).ShouldBe(VideoFormat.WebM);
        VideoContainerSniffer.Recognise("\0\0\0\u0014ftypqt  \0\0\0\0"u8.ToArray().AsSpan()).ShouldBe(VideoFormat.QuickTime);
        VideoContainerSniffer.Recognise("\0\0\0 ftypisom\0\0\u0002\0"u8.ToArray().AsSpan()).ShouldBe(VideoFormat.Mp4);
    }
}
